<script setup>
import { computed, ref, watch, onBeforeUnmount } from 'vue';
import { mobileClinicalClient } from './clinicalTransport.js';
const props=defineProps({apiBase:String,sessionToken:String,clientId:[Number,String]});
const emit=defineEmits(['back','contact']);
const summary=ref(null),loading=ref(false),busy=ref(false),error=ref(''),sms=ref(null),smsText=ref(''),sent=ref('');let generation=0;
const client=computed(()=>mobileClinicalClient(props.apiBase,props.sessionToken));
async function load(){const current=++generation;summary.value=null;loading.value=true;error.value='';try{const {data}=await client.value.get(`/clients/${props.clientId}/summary`);if(current===generation)summary.value=data;}catch(e){if(current===generation)error.value=e.response?.data?.error?.message || 'This client summary is unavailable.';}finally{if(current===generation)loading.value=false;}}
async function contact(person,channel){if(busy.value)return;busy.value=true;error.value='';try{const {data}=await client.value.post(`/clients/${props.clientId}/contact`,{recipientKey:person.key,channel});if(channel==='sms'){sms.value={...data,recipientKey:person.key,maskedName:person.maskedName};smsText.value='';}else emit('contact',data);}catch(e){error.value=e.response?.data?.error?.message || 'This contact method is unavailable.';}finally{busy.value=false;}}
async function sendSms(){if(busy.value || !smsText.value.trim())return;busy.value=true;error.value='';try{const {data}=await client.value.post(`/clients/${props.clientId}/contact/send`,{recipientKey:sms.value.recipientKey,channel:'sms',text:smsText.value});smsText.value='';sms.value=null;sent.value='Text sent.';if(data.conversationId)emit('contact',{conversationId:data.conversationId,channel:'sms'});}catch(e){error.value=e.response?.data?.error?.message || 'The text could not be sent. Your draft is preserved.';}finally{busy.value=false;}}
onBeforeUnmount(()=>{generation++;summary.value=null;sms.value=null;smsText.value='';});
watch(()=>`${props.clientId}:${props.sessionToken}`,()=>{sms.value=null;smsText.value='';sent.value='';load();},{immediate:true});
</script>
<template><section class="mobile-client-summary"><button type="button" class="mcs-back" @click="emit('back')">← Back</button><p v-if="loading" role="status">Loading client summary…</p><p v-if="error" role="alert">{{ error }}</p><p v-if="sent" role="status">{{ sent }}</p><form v-if="sms" class="mcs-sms" @submit.prevent="sendSms"><h3>Text {{ sms.maskedName || 'contact' }}</h3><p>{{ sms.to }}</p><label>Message<textarea v-model="smsText" rows="5" maxlength="4000" required /></label><button type="button" :disabled="busy" @click="sms=null">Cancel</button><button type="submit" :disabled="busy || !smsText.trim()">{{ busy?'Sending…':'Send text' }}</button></form><template v-if="summary"><header><span class="mcs-avatar" aria-hidden="true">{{ summary.client?.maskedName?.slice(0,1) || 'C' }}</span><div><p>Client summary</p><h2>{{ summary.client?.maskedName || 'Client' }}</h2><span>{{ summary.client?.age != null ? `Age ${summary.client.age}` : 'Age unavailable' }}</span></div></header><p class="mcs-limited">Contact details and authorized communication options for this client.</p><article v-for="person in summary.contacts" :key="person.key"><h3>{{ person.maskedName || 'Contact' }}</h3><small>{{ person.relationship || 'Client' }}</small><button v-if="person.email && person.channels?.email" class="mcs-contact-value" type="button" :disabled="busy" @click="contact(person,'email')">{{ person.email }}</button><button v-if="person.phone && person.channels?.sms" class="mcs-contact-value" type="button" :disabled="busy" @click="contact(person,'sms')">{{ person.phone }}</button><div class="mcs-actions"><button v-if="person.channels?.secure" type="button" :disabled="busy" @click="contact(person,'secure')">♙ Secure message</button><button v-if="person.channels?.sms" type="button" :disabled="busy" @click="contact(person,'sms')">Text</button><button v-if="person.channels?.email" type="button" :disabled="busy" @click="contact(person,'email')">Email</button></div><p v-if="!person.channels?.secure && !person.channels?.sms && !person.channels?.email">No authorized messaging method is available for this contact.</p></article><p v-if="!summary.contacts?.length">No authorized contacts are available.</p></template></section></template>
<style scoped>
.mobile-client-summary{background:#fff;padding:18px;color:#173754;min-height:60vh}.mobile-client-summary button{font:inherit;cursor:pointer}.mcs-back{border:0;border-radius:8px;background:#eef4fc;color:#1b4c76;padding:10px 13px;margin-bottom:20px}.mobile-client-summary header{display:flex;align-items:center;gap:14px}.mobile-client-summary header p{font-size:11px;text-transform:uppercase;letter-spacing:.08em;margin:0;color:#72869b}.mobile-client-summary h2{margin:5px 0;font-size:24px}.mobile-client-summary header span{font-size:13px;color:#64798d}.mobile-client-summary .mcs-avatar{display:grid;place-items:center;background:#eaf2fc;width:54px;height:54px;font-size:25px;border-radius:15px;color:#245a86}.mcs-limited{font-size:13px;line-height:1.6;color:#72869b}.mobile-client-summary article{border-top:1px solid #dfe7f0;padding:18px 0}.mobile-client-summary h3{font-size:16px;margin:0 0 5px}.mobile-client-summary small{display:block;color:#6b8193;margin-bottom:8px}.mcs-contact-value{display:block;border:0;background:transparent;padding:5px 0;color:#215c8b;overflow-wrap:anywhere;text-align:left;font-size:13px!important}.mcs-actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:12px}.mcs-actions button{border:1px solid #cad9e7;background:#f2f7fd;color:#1d537e;padding:10px 12px;border-radius:9px;font-size:12px}.mcs-actions button:first-child{background:#f4f0fa;color:#64517c;border-color:#d9cdec}.mobile-client-summary [role=alert]{color:#a12c2a}.mobile-client-summary button:disabled{opacity:.5;cursor:default}
.mcs-sms{background:#f4f8fd;border:1px solid #d3dfed;border-radius:12px;padding:14px;margin:12px 0}.mcs-sms label{font-size:13px}.mcs-sms textarea{display:block;width:100%;box-sizing:border-box;padding:10px;font:inherit;border:1px solid #cad7e4;border-radius:7px;margin:8px 0}.mcs-sms button{padding:10px 12px;margin-right:8px;border:1px solid #c7d8e8;background:#fff;border-radius:8px;color:#24577d}
</style>
